def fib4(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    # Memoization dictionary
    memo = {0: 0, 1: 0, 2: 2, 3: 0}

    # Compute Fib4 sequence up to n
    for i in range(4, n + 1):
        memo[i] = memo[i - 1] + memo[i - 2] + memo[i - 3] + memo[i - 4]

    return memo[n]
```

