def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    dp = [[0] * (capacity + 1) for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                dp[i][0] = 1

    for i in range(1, rows):
        for j in range(1, cols + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(j, 0, -1):
                if j - k + 1 <= capacity:
                    dp[i][j] = max(dp[i][j], dp[i - 1][k - 1] + 1)

