import heapq

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    visits = [[0] * cols for _ in range(rows)]
    queue = []
    result = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and visits[i][j] == 0:
                size = 0
                for x, y in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    ni, nj = i + x, j + y
                    while 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] == 1 and visits[ni][nj] == 0:
                        size += 1
                        ni += x
                        nj += y
                heapq.heappush(queue, (size, i, j))
                visits[i][j] = 1

    while queue:
        size, i, j = heapq.heappop(queue)
        result += math.ceil(size / capacity)

    return result

