def maximum(arr, k):
    # Create a min heap of k elements
    heap = arr[:k]
    heapq.heapify(heap)

    # Iterate over the remaining elements in the array
    for num in arr[k:]:
        # If the current number is greater than the smallest number in the heap, replace it
        if num > heap[0]:
            heapq.heappop(heap)
            heapq.heappush(heap, num)

    # Convert the heap to a sorted list and return it
    return sorted(heap)

