from collections import defaultdict

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    paths = defaultdict(list)
    min_path = None

    def dfs(x, y, path, steps):
        nonlocal min_path
        if steps == k:
            paths[tuple(path)].append((x, y))
            if not min_path or path < min_path[0]:
                min_path = (path, [(x, y)])
            return
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in path:
                dfs(nx, ny, path + [(nx, ny)], steps + 1)

    for i in range(n):
        for j in range(n):
            dfs(i, j, [(i, j)], 1)

    for path, coords in paths.items():
        if path < min_path[0]:
            min_path = (path, coords)

    return [grid[x][y] for x, y in min_path[1]]
